def remove_duplicates(arr):
    if not arr:
        return 0

    write_pos = 1

    for read_pos in range(1, len(arr)):
        if arr[read_pos] != arr[read_pos - 1]:
            arr[write_pos] = arr[read_pos]
            write_pos += 1

    return write_pos

