public int removeDuplicates(int[] nums) {
    if (nums.length == 0) return 0;

    int writePos = 1;

    for (int readPos = 1; readPos < nums.length; readPos++) {
        if (nums[readPos] != nums[readPos - 1]) {
            nums[writePos] = nums[readPos];
            writePos++;
        }
    }

    return writePos;
}
